import React, { useState, useEffect, useMemo, useCallback } from 'react'
import axios from 'axios'
import { toast } from 'sonner'
import { AlertTriangle, Cpu, Plus, Wrench, LayoutGrid, SlidersHorizontal, ScanLine } from 'lucide-react'
import { Button } from '@/components/ui/button'
import {
  Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter, DialogDescription,
} from '@/components/ui/dialog'
import { API_EQUIPMENTS, API_PM_SUMMARY, API_CATEGORIES } from '../../lib/urls'
import { LOCAL_STORAGE_KEY_USER, LOCAL_STORAGE_DASHBOARD_CATEGORY } from '../../lib/localStorage'
import { useCurrentProdArea } from '../../lib/customHooks/useCurrentProdArea'
import FilterAside from './components/FilterAside'
import SummaryCard from './components/SummaryCard'
import EquipmentTable from './components/EquipmentTable'
import ItemCard from './components/ItemCard'
import PaginationBar from './components/PaginationBar'
import { WARNING_DAYS } from '@/lib/globalConstant'
import EquipmentFormDialog from './components/EquipmentFormDialog'
import ScanDialog from './components/ScanDialog'
import ItemDetailDialog from './components/ItemDetailDialog'
import { SkeletonEquipmentSection, SkeletonMachinesSection, SkeletonSummarySection } from './components/SkeletonLoading'

const MACHINE_PAGE_SIZE = 18

const getPeriodStatus = (p) => {
  if (p.is_overdue) return 'overdue'
  if (p.days_until_due != null && p.days_until_due <= WARNING_DAYS) return 'warning'
  if (p.days_until_due != null) return 'on_time'
  if (p.pending_approval && p.last_pm_date === null) return 'pending_approval'
  return 'new'
}

const STATUS_RANK = { overdue: 0, warning: 1, new: 2, pending_approval: 3, on_time: 4 }

const getItemStatus = (periods) => {
  const list = periods ?? []
  if (list.length === 0) return 'new'
  return list.reduce((worst, p) => {
    const s = getPeriodStatus(p)
    return STATUS_RANK[s] < STATUS_RANK[worst] ? s : worst
  }, 'on_time')
}

const getPeriodName = (p) => p.custom_period_name || p.period_name || `${p.pm_period ?? '?'}d`

const aggregateByCategory = (items) => {
  const map = {}
  for (const eq of items) {
    const key = eq.category_name
    if (!map[key]) {
      map[key] = {
        category_name: eq.category_name,
        category_type: eq.category_type,
        on_time: 0,
        warning: 0,
        overdue: 0,
        pending_approval: 0,
        new: 0,
        sample_image: null,
      }
    }
    map[key][getItemStatus(eq.periods ?? [])] += 1
    if (!map[key].sample_image && eq.image) map[key].sample_image = eq.image
  }
  return Object.values(map)
}

const aggregatePeriodsForCategory = (items, categoryName) => {
  const map = {}
  for (const eq of items) {
    if (eq.category_name !== categoryName) continue
    for (const p of eq.periods ?? []) {
      const key = getPeriodName(p)
      if (!map[key]) {
        map[key] = { period_name: key, on_time: 0, warning: 0, overdue: 0, pending_approval: 0, new: 0 }
      }
      map[key][getItemStatus([p])] += 1
    }
  }
  return Object.values(map).sort((a, b) => a.period_name.localeCompare(b.period_name))
}

const unique = (arr) => {
  return [...new Set(arr.filter(Boolean))].sort()
}

const matchesSearch = (item, term) => {
  if (!term) return true
  const t = term.toLowerCase()
  return [
    item.equipment_number,
    item.model,
    item.part_number,
    item.location,
    item.station,
    item.incharge_name,
    item.category_name,
  ].some(v => v != null && String(v).toLowerCase().includes(t))
}

const SectionHeader = ({ icon: Icon, label, count }) => {
  return (
    <div className="flex items-center gap-2 mb-2">
      <Icon size={13} className="text-slate-400" />
      <span className="text-[11px] font-bold uppercase tracking-widest text-slate-500">{label}</span>
      <span className="text-[10px] font-semibold text-slate-400 bg-slate-100 px-1.5 py-0.5 rounded-full">{count}</span>
      <div className="flex-1 h-px bg-slate-200" />
    </div>
  )
}

const CategorySubHeader = ({ name, count }) => {
  return (
    <div className="flex items-center gap-2 mb-1.5">
      <span className="text-[11px] font-semibold text-slate-600">{name}</span>
      <span className="text-[10px] text-slate-400 bg-slate-100 px-1.5 py-0.5 rounded-full">{count}</span>
      <div className="flex-1 h-px bg-slate-100" />
    </div>
  )
}

const MachineGroup = ({ category_name, items, onEdit, onDelete, onRefresh }) => {
  const [page, setPage] = useState(1)
  const totalPages = Math.ceil(items.length / MACHINE_PAGE_SIZE)
  const paged = items.slice((page - 1) * MACHINE_PAGE_SIZE, page * MACHINE_PAGE_SIZE)

  useEffect(() => setPage(1), [items.length])

  return (
    <div>
      <CategorySubHeader name={category_name} count={items.length} />
      <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-5 lg:grid-cols-4 3xl:grid-cols-6 gap-3">
        {paged.map((item, idx) => (
          <ItemCard key={item.id ?? idx} item={item} onEdit={onEdit} onDelete={onDelete} onRefresh={onRefresh} />
        ))}
      </div>
      {totalPages > 1 && (
        <div className="mt-3 bg-white border border-slate-200 rounded-xl overflow-hidden shadow-sm">
          <PaginationBar
            page={page}
            totalPages={totalPages}
            total={items.length}
            pageSize={MACHINE_PAGE_SIZE}
            onPageChange={setPage}
          />
        </div>
      )}
    </div>
  )
}


export default function Dashboard() {
  const prodArea = useCurrentProdArea()

  const [allItems, setAllItems] = useState([])
  // Categories are tagged with the area they were fetched for, so the summary fetch
  // can tell "categories for the current area" apart from ones left over from the previous area.
  const [asideCategories, setAsideCategories] = useState({ area: null, list: [] })
  const [loading, setLoading] = useState(true)
  const [contentLoading, setContentLoading] = useState(false)
  const [refreshKey, setRefreshKey] = useState(0)

  const [categorySelection, setCategorySelection] = useState(() => {
    try {
      const saved = JSON.parse(localStorage.getItem(LOCAL_STORAGE_DASHBOARD_CATEGORY))
      if (saved?.type && saved?.name) return saved
    } catch { 

    }
    return { type: 'machine', name: null }
  })
  const [locationFilter, setLocationFilter] = useState('all')
  const [picFilter, setPicFilter] = useState('all')
  const [statusFilter, setStatusFilter] = useState([])
  const [searchTerm, setSearchTerm] = useState('')

  const [equipFormOpen, setEquipFormOpen] = useState(false)
  const [editTarget, setEditTarget] = useState(null)
  const [deleteOpen, setDeleteOpen] = useState(false)
  const [deleteTarget, setDeleteTarget] = useState(null)
  const [deleting, setDeleting] = useState(false)
  const [filterOpen, setFilterOpen] = useState(false)

  const [scanOpen, setScanOpen] = useState(false)
  const [scanItem, setScanItem] = useState(null)
  const [scanDetailOpen, setScanDetailOpen] = useState(false)

  const raw = localStorage.getItem(LOCAL_STORAGE_KEY_USER)
  const token = raw ? JSON.parse(raw).token : null
  const config = { headers: { ...(token && { Authorization: `Token ${token}` }) } }

  useEffect(() => {
    document.title = "PMS+ | Dashboard"
  }, [])

  // Step 1: categories for the current production area
  useEffect(() => {
    if (!prodArea) return
    let cancelled = false
    setLoading(true)
    axios
      .get(`${API_CATEGORIES}?prod_area_name=${encodeURIComponent(prodArea)}`, config)
      .then(res => {
        if (cancelled) return
        setAsideCategories({ area: prodArea, list: res.data })
      })
      .catch(err => {
        if (cancelled) return
        console.error('Failed to fetch categories:', err)
        toast.error('Failed to load dashboard data. Please try refreshing the page.')
        setLoading(false)
      })
    return () => { cancelled = true }
  }, [prodArea])

  const handleCategoryChange = useCallback((newSelection) => {
    setCategorySelection(newSelection)
  }, [])

  const handleClearAllFilters = useCallback(() => {
    setLocationFilter('all')
    setPicFilter('all')
    setStatusFilter([])
    setSearchTerm('')
  }, [])

  const handleEdit = useCallback((item) => {
    setEditTarget(item)
    setEquipFormOpen(true)
  }, [])

  const handleDelete = useCallback((item) => {
    setDeleteTarget(item)
    setDeleteOpen(true)
  }, [])

  const handleScanMatch = useCallback((item) => {
    setScanOpen(false)
    setScanItem(item)
    setScanDetailOpen(true)
  }, [])

  const handleDeleteConfirm = useCallback(async () => {
    if (!deleteTarget) return
    // console.log(`delete : ${JSON.stringify(deleteTarget, null, 2)}`)
    const raw = localStorage.getItem(LOCAL_STORAGE_KEY_USER)
    const token = raw ? JSON.parse(raw).token : null
    const config = { headers: { ...(token && { Authorization: `Token ${token}` }) } }
    setDeleting(true)
    try {
      await axios.delete(`${API_EQUIPMENTS}${deleteTarget.equipment_number}/`, config)
      toast.success('Equipment deleted')
      setDeleteOpen(false)
      setDeleteTarget(null)
      setRefreshKey(k => k + 1)
    } catch {
      toast.error('Failed to delete equipment')
    } finally {
      setDeleting(false)
    }
  }, [deleteTarget])

  useEffect(() => {
    setLocationFilter('all')
    setPicFilter('all')
    setStatusFilter([])
    setSearchTerm('')
  }, [categorySelection.type])

  const typeItems = useMemo(() => {
    if (categorySelection.type === 'all') return allItems
    return allItems.filter(i => i.category_type === categorySelection.type)
  }, [allItems, categorySelection.type])

  const locations = useMemo(() => unique(typeItems.map(i => i.location)), [typeItems])
  const pics = useMemo(
    () => unique(typeItems.map(i => i.incharge_name)),
    [typeItems],
  )
  const categoryGroups = useMemo(() => {
    const map = {}
    for (const cat of asideCategories.list) {
      const t = cat.category_type
      if (!t) continue
      if (!map[t]) map[t] = new Set()
      if (cat.name) map[t].add(cat.name)
    }
    return Object.fromEntries(
      Object.entries(map).map(([t, names]) => [t, [...names].sort()])
    )
  }, [asideCategories.list])

  const categoriesReady = asideCategories.area === prodArea
  const selectionValid = Boolean(categorySelection.name) && Boolean(categoryGroups[categorySelection.type]?.includes(categorySelection.name))

  // Step 2: once categories for this area arrive, make sure the selected category belongs to it
  // (the saved selection may be left over from another area)
  useEffect(() => {
    if (!categoriesReady) return
    const types = Object.keys(categoryGroups)
    if (types.length === 0) {
      setAllItems([])
      setLoading(false)
      setContentLoading(false)
      return
    }
    if (selectionValid) return
    const firstType = types[0]
    const firstName = categoryGroups[firstType]?.[0]
    if (firstName) setCategorySelection({ type: firstType, name: firstName })
  }, [categoriesReady, categoryGroups, selectionValid])

  // Step 3: summary for the selected category, scoped to the current area
  useEffect(() => {
    if (!categoriesReady || !selectionValid) return
    let cancelled = false
    setContentLoading(true)
    axios
      .get(`${API_PM_SUMMARY}?category_name=${encodeURIComponent(categorySelection.name)}&prod_area_name=${encodeURIComponent(prodArea)}`, config)
      .then(res => {
        if (cancelled) return
        setAllItems(res.data)
      })
      .catch(err => {
        if (cancelled) return
        console.error('Failed to fetch summary data:', err)
        toast.error('Failed to load summary data. Please try again.')
      })
      .finally(() => {
        if (cancelled) return
        setLoading(false)
        setContentLoading(false)
      })
    return () => { cancelled = true }
  }, [categoriesReady, selectionValid, categorySelection.name, prodArea, refreshKey])

  useEffect(() => {
    if (categorySelection.name) {
      localStorage.setItem(LOCAL_STORAGE_DASHBOARD_CATEGORY, JSON.stringify(categorySelection))
    }
  }, [categorySelection])

  const filteredItems = useMemo(() => allItems.filter(item => {
    if (locationFilter !== 'all' && item.location !== locationFilter) return false
    const pic = item.incharge_name
    if (picFilter !== 'all' && pic !== picFilter) return false

    if (statusFilter.length > 0) {
      const periods = item.periods ?? []
      // An item matches if any of its individual periods' statuses match the filter selection.
      // If no periods exist, it is treated as 'new' (aggregated default).
      const matches = periods.length === 0
        ? statusFilter.includes('new')
        : periods.some(p => statusFilter.includes(getItemStatus([p])))

      if (!matches) return false
    }

    return true
  }), [allItems, locationFilter, picFilter, statusFilter])

  // Summary cards always reflect all items — location/PIC filters only affect the item grids below
  const categories = useMemo(() => aggregateByCategory(allItems), [allItems])

  const isCategoryDrilldown = Boolean(categorySelection.name)

  // Summary cards: filter by type; when a specific category is selected, show only that card
  const summaryDisplayed = useMemo(() => categories
    .filter(c => {
      if (categorySelection.type !== 'all' && c.category_type !== categorySelection.type) return false
      if (categorySelection.name && c.category_name !== categorySelection.name) return false
      return true
    }),
    [categories, categorySelection],
  )

  const periodBreakdown = useMemo(() => {
    if (!categorySelection.name) return null
    return aggregatePeriodsForCategory(allItems, categorySelection.name)
  }, [allItems, categorySelection.name])

  // Machine items
  const machineGroups = useMemo(() => {
    const grouped = {}
    for (const item of filteredItems) {
      if (item.category_type !== 'machine') continue
      if (categorySelection.type === 'equipment') continue
      if (categorySelection.type === 'machine' && categorySelection.name && item.category_name !== categorySelection.name) continue
      if (!matchesSearch(item, searchTerm)) continue
      if (!grouped[item.category_name]) grouped[item.category_name] = []
      grouped[item.category_name].push(item)
    }
    return Object.entries(grouped).map(([name, items]) => ({
      category_name: name,
      items: items.sort((a, b) => {
        const rank = STATUS_RANK
        return rank[getItemStatus(a.periods)] - rank[getItemStatus(b.periods)]
      }),
    }))
  }, [filteredItems, categorySelection, searchTerm])

  // Equipment items
  const equipmentItems = useMemo(() => {
    return filteredItems
      .filter(item => {
        if (item.category_type !== 'equipment') return false
        if (categorySelection.type === 'machine') return false
        if (categorySelection.type === 'equipment' && categorySelection.name && item.category_name !== categorySelection.name) return false
        if (!matchesSearch(item, searchTerm)) return false
        return true
      })
      .sort((a, b) => {
        const rank = STATUS_RANK
        return rank[getItemStatus(a.periods)] - rank[getItemStatus(b.periods)]
      })
  }, [filteredItems, categorySelection, searchTerm])

  const totalMachineItems = useMemo(
    () => machineGroups.reduce((s, g) => s + g.items.length, 0),
    [machineGroups],
  )

  const isEmpty = summaryDisplayed.length === 0 && machineGroups.length === 0 && equipmentItems.length === 0

  const activeFilterCount = (locationFilter !== 'all' ? 1 : 0) + (picFilter !== 'all' ? 1 : 0) + statusFilter.length + (searchTerm !== '' ? 1 : 0)

  return (
    <div className="min-h-dvh bg-blue-50 p-4">
      <div className="mb-4 flex items-start justify-between">
        <div>
          <h1 className="text-lg font-bold text-slate-800">Dashboard</h1>
          <p className="text-xs text-slate-500 mt-0.5">Overview of equipment and machine PM status</p>
        </div>
        <div className="flex items-center gap-2">
          <button
            onClick={() => setFilterOpen(true)}
            className={`xl:hidden flex items-center gap-1.5 px-3 py-1.5 text-xs font-semibold rounded-xl shadow-sm transition-colors cursor-pointer border ${
              activeFilterCount > 0
                ? 'bg-blue-500 border-blue-500 text-white hover:bg-blue-600'
                : 'bg-white border-slate-200 text-slate-600 hover:bg-slate-50'
            }`}
          >
            <SlidersHorizontal size={13} />
            Filters
            {activeFilterCount > 0 && (
              <span className="relative flex items-center justify-center">
                <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-white/60 opacity-75" />
                <span className="relative bg-white/30 text-white text-[10px] font-bold px-1.5 py-0.5 rounded-full leading-none">
                  {activeFilterCount}
                </span>
              </span>
            )}
          </button>
          <Button
            size="sm"
            variant="outline"
            onClick={() => setScanOpen(true)}
            className="flex items-center gap-1.5 px-4 rounded-md text-sm font-medium border-slate-200 text-slate-600 hover:bg-slate-50 transition-colors cursor-pointer"
          >
            <ScanLine className="w-4 h-4" />
            Scan
          </Button>
          <Button
            size="sm"
            onClick={() => { setEditTarget(null); setEquipFormOpen(true) }}
            className="flex items-center gap-1.5 px-4 rounded-md text-sm font-medium bg-blue-500 text-white hover:bg-blue-600 transition-colors cursor-pointer disabled:opacity-50 disabled:pointer-events-none"
          >
            <Plus className="w-4 h-4" />
            Add Equipment
          </Button>
        </div>
      </div>

      <div className="flex gap-4">
        <div className="hidden xl:block w-56 shrink-0">
          {/* Filter */}
          <FilterAside
            loading={loading}
            categoryGroups={categoryGroups}
            locations={locations}
            pics={pics}
            categorySelection={categorySelection}
            onCategoryChange={handleCategoryChange}
            locationFilter={locationFilter}
            onLocationChange={setLocationFilter}
            picFilter={picFilter}
            onPicChange={setPicFilter}
            statusFilter={statusFilter}
            onStatusChange={setStatusFilter}
            searchTerm={searchTerm}
            onSearchChange={setSearchTerm}
            onClearAll={handleClearAllFilters}
          />
        </div>

        <div className="flex-1 min-w-0 space-y-4">
          {loading || contentLoading ? (
            <>
              <SkeletonSummarySection />
              <SkeletonMachinesSection />
              <SkeletonEquipmentSection />
            </>

          ) : isEmpty ? (
            <div className="flex flex-col items-center justify-center py-32 text-slate-400">
              <p className="text-sm font-medium">No categories match the current filters</p>
              <p className="text-xs mt-1">Try adjusting or clearing the filters</p>
            </div>
          ) : (
            <>
              {summaryDisplayed.length > 0 && (
                <section>
                  <SectionHeader icon={LayoutGrid} label="Summary" count={summaryDisplayed.length} />
                  <div className={
                    isCategoryDrilldown
                      ? 'w-full'
                      : 'flex gap-3 overflow-x-auto [&::-webkit-scrollbar]:hidden [-ms-overflow-style:none] [scrollbar-width:none] xl:grid xl:grid-cols-3 2xl:grid-cols-4 xl:overflow-x-visible xl:gap-4'
                  }>
                    {summaryDisplayed.map(cat => (
                      <div key={cat.category_name} className={isCategoryDrilldown ? 'w-full' : 'w-70 xl:w-full shrink-0 sm:min-w-0 sm:shrink'}>
                        <SummaryCard
                          data={cat}
                          expanded={isCategoryDrilldown}
                          periodBreakdown={isCategoryDrilldown ? periodBreakdown : null}
                        />
                      </div>
                    ))}
                  </div>
                </section>
              )}

              {machineGroups.length > 0 && (
                <section>
                  {/* <SectionHeader icon={Cpu} label="Machines" count={totalMachineItems} /> */}
                  <div className="space-y-5">
                    {machineGroups.map(group => (
                      <MachineGroup key={group.category_name} category_name={group.category_name} items={group.items} onEdit={handleEdit} onDelete={handleDelete} onRefresh={() => setRefreshKey(k => k + 1)} />
                    ))}
                  </div>
                </section>
              )}

              {equipmentItems.length > 0 && (
                <section>
                  {/* <SectionHeader icon={Wrench} label="Equipment" count={equipmentItems.length} /> */}
                  <EquipmentTable items={equipmentItems} onEdit={handleEdit} onDelete={handleDelete} onRefresh={() => setRefreshKey(k => k + 1)} />
                </section>
              )}
            </>
          )}
        </div>
      </div>

      {/* Backdrop */}
      <div
        onClick={() => setFilterOpen(false)}
        className={`fixed inset-0 z-40 bg-black/30 xl:hidden transition-opacity duration-300 ${
          filterOpen ? 'opacity-100 pointer-events-auto' : 'opacity-0 pointer-events-none'
        }`}
      />

      {/* Bottom sheet */}
      <div
        className={`fixed bottom-0 inset-x-0 z-50 xl:hidden bg-white rounded-t-2xl shadow-2xl max-h-[80vh] flex flex-col transform transition-transform duration-300 ${
          filterOpen ? 'translate-y-0' : 'translate-y-full'
        }`}
      >
        <div className="flex justify-center pt-3 pb-0 shrink-0">
          <div className="w-10 h-1 bg-slate-200 rounded-full" />
        </div>
        <FilterAside
          className="flex-1 min-h-0 flex flex-col overflow-hidden"
          onClose={() => setFilterOpen(false)}
          loading={loading}
          categoryGroups={categoryGroups}
          locations={locations}
          pics={pics}
          categorySelection={categorySelection}
          onCategoryChange={handleCategoryChange}
          locationFilter={locationFilter}
          onLocationChange={setLocationFilter}
          picFilter={picFilter}
          onPicChange={setPicFilter}
          statusFilter={statusFilter}
          onStatusChange={setStatusFilter}
          searchTerm={searchTerm}
          onSearchChange={setSearchTerm}
          onClearAll={handleClearAllFilters}
        />
      </div>

      <EquipmentFormDialog
        open={equipFormOpen}
        onClose={() => { setEquipFormOpen(false); setEditTarget(null) }}
        equipment={editTarget}
        onSuccess={() => setRefreshKey(k => k + 1)}
      />

      <ScanDialog
        open={scanOpen}
        onOpenChange={setScanOpen}
        items={allItems}
        onMatch={handleScanMatch}
      />

      <ItemDetailDialog
        item={scanItem}
        open={scanDetailOpen}
        onOpenChange={setScanDetailOpen}
        onEdit={handleEdit}
        onDelete={handleDelete}
        onRefresh={() => setRefreshKey(k => k + 1)}
      />

      <Dialog open={deleteOpen} onOpenChange={v => { if (!v) { setDeleteOpen(false); setDeleteTarget(null) } }}>
        <DialogContent className="sm:max-w-sm">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2 text-red-600">
              <AlertTriangle className="w-5 h-5" />
              Confirm Deletion
            </DialogTitle>
            <DialogDescription>This action cannot be undone.</DialogDescription>
          </DialogHeader>
          {deleteTarget && (
            <div className="flex flex-col gap-1 p-3 border border-red-200 rounded-md bg-red-50 text-sm">
              <div className="flex justify-between">
                <span className="text-slate-600 font-medium">Equipment No.</span>
                <span className="text-slate-800 font-semibold">{deleteTarget.equipment_number}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-slate-600 font-medium">Model</span>
                <span className="text-slate-800">{deleteTarget.model || '—'}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-slate-600 font-medium">Part Number</span>
                <span className="text-slate-800">{deleteTarget.part_number || '—'}</span>
              </div>
            </div>
          )}
          <DialogFooter>
            <Button variant="outline" className="cursor-pointer" onClick={() => { setDeleteOpen(false); setDeleteTarget(null) }} disabled={deleting}>
              Cancel
            </Button>
            <Button variant="destructive" className="cursor-pointer" onClick={handleDeleteConfirm} disabled={deleting}>
              {deleting ? 'Deleting...' : 'Delete'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  )
}

