class EquipmentViewSet(ProdAreaFilterMixin, BaseViewSet):
    lookup_field = 'equipment_number'
    lookup_value_regex = '[^/]+'
    filter_backends = [filters.SearchFilter, filters.OrderingFilter]
    search_fields = ['equipment_number', 'equipment_model__model', 'equipment_model__part_number', 'location']
    ordering_fields = ['equipment_number', 'equipment_model__model', 'created_at']
    ordering = ['equipment_number']

    def get_queryset(self):
        qs = Equipment.objects.select_related(
            'equipment_model__category', 'equipment_model__pm_checklist', 'production_area',
            'equipment_model__esd_spec', 'equipment_model__category__esd_spec',
        ).prefetch_related(
            'pm_schedules__pm_period',
            Prefetch(
                'pm_schedules__pm_period__sops',
                queryset=PmSop.objects.filter(is_esd_source=True),
                to_attr='esd_sops',
            ),
            Prefetch(
                'pm_records',
                queryset=PmRecord.objects.filter(status=PmRecord.STATUS_SUBMITTED).select_related('current_workflow_step').order_by('-performed_at'),
                to_attr='pending_records',
            ),
        )
        params = self.request.query_params

        category = params.get('category')
        if category:
            qs = qs.filter(equipment_model__category_id=category)

        category_name = params.get('category_name')
        if category_name:
            qs = qs.filter(equipment_model__category__name__icontains=category_name)

        equipment_status = params.get('status')
        if equipment_status:
            qs = qs.filter(status=equipment_status)

        category_type = params.get('category_type')
        if category_type:
            qs = qs.filter(equipment_model__category__category_type=category_type)

        qs = self.filter_prod_area(qs)

        now = timezone.now()

        if params.get('overdue') == 'true':
            qs = qs.filter(pm_schedules__next_pm_date__lt=now).distinct()

        due_within_days = params.get('due_within_days')
        if due_within_days:
            try:
                qs = qs.filter(
                    pm_schedules__next_pm_date__range=(now, now + timedelta(days=int(due_within_days)))
                ).distinct()
            except ValueError:
                pass

        return qs

    def get_serializer_class(self):
        if self.action == 'pm_summary':
            return EquipmentScheduleSummarySerializer
        if self.action == 'list':
            return EquipmentListSerializer
        if self.action in ('create', 'update', 'partial_update'):
            return EquipmentWriteSerializer
        return EquipmentDetailSerializer

